sysauto_script.script:
// WhereUsed Radar — scheduled weekly impact scan
// Copyright (C) 2026 Vladimir Kapustin
// SPDX-License-Identifier: AGPL-3.0
(function runWhereUsedRadarWeeklyScan() {
    try {
        var scanner = new WurScanner();
        // Target objects are supplied by the caller (UI action / REST) or a
        // system property. When none are configured, the job is a no-op that
        // logs a reminder rather than scanning an empty target set.
        var targets = gs.getProperty('x_sn_wur.scan_targets', '');
        if (!targets) {
            gs.info('WhereUsed Radar weekly scan skipped: no targets configured (x_sn_wur.scan_targets).');
            return;
        }
        var list = targets.split(',');
        for (var i = 0; i < list.length; i++) {
            var parts = list[i].trim().split(':');
            if (parts.length !== 2) { continue; }
            var scanId = scanner.runScan(parts[0], parts[1]);
            gs.info('WhereUsed Radar weekly scan complete: target=' + list[i].trim() +
                ', scan_id=' + scanId);
        }
    } catch (e) {
        gs.error('WhereUsed Radar weekly scan failed: ' + e.message);
    }
})();
